        [Test]
        public void UploadImage_ValidFile_ShouldReturn200()
        {
            var petId = 1;
            var request = new RestRequest($"pet/{petId}/uploadImage", Method.POST);
            request.AlwaysMultipartFormData = true;
            request.AddParameter("additionalMetadata", "test image upload");
            var relativePath = @"Assets\cooking.jpg";
            var filePath = Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, relativePath));
            request.AddFile("file", filePath, "image/jpeg");
            var response = client.Execute(request);
            Assert.That((int)response.StatusCode, Is.EqualTo(200)); 
        }

